def solve_S_final(S):
    max_k = 0
    for n in range(0, 2 * S + 1):
        for m in range(0, 2 * S + 1):
            possible = False
            if n > m:
                upper = min(1.0, (S - m) / (n - m))
                if upper > 0.5:
                    possible = True
            elif n == m:
                if S > m:
                    possible = True
            else: # n < m
                lower = max(0.5, (S - m) / (n - m))
                if lower < 1.0:
                    possible = True

            if possible:
                max_k = max(max_k, n + (m + 1) // 2)
    return max_k

print(f"For S=59: {solve_S_final(59)}")

